using System;
using System.Collections.Generic;
using UnityEngine;

namespace BiologyVR.V2
{
    /// <summary>Knowledge entries (grade 8–9, basic level). A scan reveals the entry once:
    /// a short hologram with three callouts and one professor line; the full text lives in the codex.</summary>
    public sealed class Bvr2Codex : MonoBehaviour
    {
        [Serializable]
        public class Entry
        {
            public string id, title, line, codex; public string[] callouts; public string diorama; public Color color;
            public int chapter = 1;
        }

        public readonly List<Entry> entries = new List<Entry>();
        readonly HashSet<string> found = new HashSet<string>();
        public event Action<Entry> OnDiscovered;
        public int FoundCount => found.Count;
        public int CountIn(int chapter) { int n = 0; foreach (var e in entries) if (e.chapter == chapter) n++; return n; }
        public int FoundIn(int chapter) { int n = 0; foreach (var e in entries) if (e.chapter == chapter && found.Contains(e.id)) n++; return n; }
        /// <summary>Forget one chapter's entries (replaying that chapter).</summary>
        public void ResetChapter(int chapter) { foreach (var e in entries) if (e.chapter == chapter) found.Remove(e.id); }
        int addingChapter = 1;
        public bool Has(string id) => found.Contains(id);

        void Awake() { Fill(); }

        public Entry Get(string id) { foreach (var e in entries) if (e.id == id) return e; return null; }

        /// <summary>Returns true the first time.</summary>
        public bool Discover(string id)
        {
            var e = Get(id); if (e == null || !found.Add(id)) return false;
            OnDiscovered?.Invoke(e); return true;
        }

        public void ResetFound() => found.Clear();
        /// <summary>Debug: forget one entry so it can be revealed again.</summary>
        public void Forget(string id) => found.Remove(id);

        void Add(string id, string title, string diorama, Color color, string line, string codex, params string[] callouts)
            => entries.Add(new Entry { id = id, title = title, diorama = diorama, color = color, line = line, codex = codex, callouts = callouts, chapter = addingChapter });

        void Fill()
